import { createHash } from 'node:crypto';
import { COLD_WORKSPACE_TOOL_SNAPSHOT } from './cold-tools.generated.js';
import { SwarmError } from './errors.js';

/** Protocol revision served by the swarm MCP bridge. */
export const COLD_WORKSPACE_PROTOCOL_VERSION = '2026-07-28';

/**
 * One tool of the workspace provider as returned by its real `tools/list`.
 *
 * The snapshot is generated by `scripts/generate-workspace-tool-snapshot.mjs`
 * from `peri mcp-start peri --capability workspace --stdio`, so the cold face
 * and the sandboxed provider come from the same `peri-mcp-workspace` crate.
 */
export interface ColdWorkspaceTool {
  readonly name: string;
  readonly description: string;
  readonly inputSchema: Record<string, unknown>;
}

export interface ColdWorkspaceProviderVersionDiagnostics {
  readonly expected: string;
  readonly actual: string;
  readonly consistent: boolean;
}

export interface ColdWorkspaceDiagnostics {
  readonly providerVersion: ColdWorkspaceProviderVersionDiagnostics;
  readonly snapshot: {
    readonly protocolVersion: string;
    readonly source: string;
    readonly digest: string;
  };
}

export interface ColdWorkspaceToolSnapshot {
  readonly providerName: string;
  readonly providerVersion: string;
  readonly protocolVersion: string;
  readonly sourceCommand: string;
  readonly toolsDigest: string;
  readonly tools: readonly ColdWorkspaceTool[];
}

function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map((item) => canonicalJson(item)).join(',')}]`;
  if (value !== null && typeof value === 'object') {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonicalJson(record[key])}`)
      .join(',')}}`;
  }
  return JSON.stringify(value);
}

function invalidSnapshot(reason: string): never {
  throw new SwarmError('invalid_config', `cold workspace tool snapshot is invalid: ${reason}`);
}

function loadSnapshot(raw: unknown): ColdWorkspaceToolSnapshot {
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) invalidSnapshot('not an object');
  const snapshot = raw as Record<string, unknown>;
  const providerName = snapshot.providerName;
  const providerVersion = snapshot.providerVersion;
  const protocolVersion = snapshot.protocolVersion;
  const sourceCommand = snapshot.sourceCommand;
  const toolsDigest = snapshot.toolsDigest;
  if (typeof providerName !== 'string' || providerName.length === 0) invalidSnapshot('providerName is empty');
  if (typeof providerVersion !== 'string' || providerVersion.length === 0) invalidSnapshot('providerVersion is empty');
  if (protocolVersion !== COLD_WORKSPACE_PROTOCOL_VERSION)
    invalidSnapshot(`protocolVersion must be ${COLD_WORKSPACE_PROTOCOL_VERSION}`);
  if (typeof sourceCommand !== 'string' || sourceCommand.length === 0) invalidSnapshot('sourceCommand is empty');
  if (typeof toolsDigest !== 'string' || !toolsDigest.startsWith('sha256:')) invalidSnapshot('toolsDigest is missing');
  if (!Array.isArray(snapshot.tools) || snapshot.tools.length === 0) invalidSnapshot('tools is empty');

  const names = new Set<string>();
  const tools = snapshot.tools.map((tool) => {
    if (tool === null || typeof tool !== 'object' || Array.isArray(tool)) invalidSnapshot('tool is not an object');
    const candidate = tool as Record<string, unknown>;
    const name = candidate.name;
    const description = candidate.description;
    const inputSchema = candidate.inputSchema;
    if (typeof name !== 'string' || name.length === 0) invalidSnapshot('tool name is empty');
    if (typeof description !== 'string' || description.length === 0)
      invalidSnapshot(`tool ${name} has an empty description`);
    if (inputSchema === null || typeof inputSchema !== 'object' || Array.isArray(inputSchema))
      invalidSnapshot(`tool ${name} has no inputSchema object`);
    if (names.has(name)) invalidSnapshot(`duplicate tool name ${name}`);
    names.add(name);
    return { name, description, inputSchema: inputSchema as Record<string, unknown> };
  });

  const digest = `sha256:${createHash('sha256').update(canonicalJson(tools)).digest('hex')}`;
  if (digest !== toolsDigest) invalidSnapshot('toolsDigest does not match the embedded tools');
  return {
    providerName,
    providerVersion,
    protocolVersion,
    sourceCommand,
    toolsDigest,
    tools,
  };
}

/** Validated snapshot; module load fails fast if the generated file drifts from its digest. */
export const COLD_WORKSPACE_SNAPSHOT: ColdWorkspaceToolSnapshot = loadSnapshot(COLD_WORKSPACE_TOOL_SNAPSHOT);

/** Version the swarm bridge expects from the workspace provider (overridable per server). */
export const COLD_WORKSPACE_PROVIDER_VERSION = COLD_WORKSPACE_SNAPSHOT.providerVersion;

/** Stable marker attached to every cold MCP response. */
export const COLD_SNAPSHOT_META_KEY = 'peri.swarmColdSnapshot';

/** Version/diagnostic metadata key attached to every cold MCP response. */
export const COLD_DIAGNOSTICS_META_KEY = 'peri.swarmDiagnostics';

/** Standard 2026-07-28 identity stamp key (servers SHOULD identify themselves on every result). */
const SERVER_INFO_META_KEY = 'io.modelcontextprotocol/serverInfo';

/** Diagnostics compare the deployment expectation with the snapshot that answers cold requests. */
export function coldWorkspaceDiagnostics(expectedProviderVersion: string): ColdWorkspaceDiagnostics {
  return {
    providerVersion: {
      expected: expectedProviderVersion,
      actual: COLD_WORKSPACE_SNAPSHOT.providerVersion,
      consistent: expectedProviderVersion === COLD_WORKSPACE_SNAPSHOT.providerVersion,
    },
    snapshot: {
      protocolVersion: COLD_WORKSPACE_SNAPSHOT.protocolVersion,
      source: COLD_WORKSPACE_SNAPSHOT.sourceCommand,
      digest: COLD_WORKSPACE_SNAPSHOT.toolsDigest,
    },
  };
}

function coldMeta(expectedProviderVersion: string): Record<string, unknown> {
  return {
    [SERVER_INFO_META_KEY]: {
      name: COLD_WORKSPACE_SNAPSHOT.providerName,
      version: COLD_WORKSPACE_SNAPSHOT.providerVersion,
    },
    [COLD_SNAPSHOT_META_KEY]: true,
    providerVersion: COLD_WORKSPACE_SNAPSHOT.providerVersion,
    'peri.swarmProviderVersion': COLD_WORKSPACE_SNAPSHOT.providerVersion,
    [COLD_DIAGNOSTICS_META_KEY]: coldWorkspaceDiagnostics(expectedProviderVersion),
  };
}

/**
 * Cold `initialize` result.
 *
 * Only the tool capability is advertised: resources/prompts would require a
 * running provider, and advertising them here would promise a surface the
 * snapshot cannot answer.
 */
export function coldInitializeResult(expectedProviderVersion: string): Record<string, unknown> {
  return {
    protocolVersion: COLD_WORKSPACE_PROTOCOL_VERSION,
    capabilities: { tools: { listChanged: false } },
    serverInfo: {
      name: COLD_WORKSPACE_SNAPSHOT.providerName,
      version: COLD_WORKSPACE_SNAPSHOT.providerVersion,
    },
    _meta: coldMeta(expectedProviderVersion),
  };
}

/** Cold `server/discover` result (2026-07-28 revision negotiation). */
export function coldDiscoverResult(expectedProviderVersion: string): Record<string, unknown> {
  // The 2026-07-28 DiscoverResult schema requires `resultType`, `ttlMs` and
  // `cacheScope`; rmcp rejects a result missing them as an unknown
  // `CustomResult` and aborts before any `tools/call` can lazily start SRT.
  return {
    resultType: 'complete',
    supportedVersions: [COLD_WORKSPACE_PROTOCOL_VERSION],
    capabilities: { tools: { listChanged: false } },
    ttlMs: 0,
    cacheScope: 'private',
    _meta: coldMeta(expectedProviderVersion),
  };
}

/** Cold `tools/list` result: the real provider's tools plus snapshot provenance. */
export function coldToolsListResult(expectedProviderVersion: string): Record<string, unknown> {
  return {
    tools: COLD_WORKSPACE_SNAPSHOT.tools.map((tool) => ({
      name: tool.name,
      description: tool.description,
      inputSchema: tool.inputSchema,
    })),
    _meta: coldMeta(expectedProviderVersion),
  };
}
